function CatHouseRegisterPanel:InitData()
    --- 集会登记位上限
    self.registerMaxSeat  = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupSeatUpLimit).num)
    --- 集会中使用货币id
    self.rallyGoodsId  = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)

    self:InitSignUpInfo()
end

function CatHouseRegisterPanel:InitSignUpInfo()
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    local maxSignUpNum     = checkNumber(catHouseHomeDojo.maxSignUpNum)
    local rallySignupList  = catHouseHomeDojo.rallySignupList
    local rallyId2Data     = {}
    for i, rallySignupData in ipairs(rallySignupList) do
        rallyId2Data[checkNumber(rallySignupData.rallyId)] = rallySignupData
    end

    self.rallyId2Data = rallyId2Data
    self.maxSignUpNum = maxSignUpNum
end


