function CatHouseRegisterPanel:FreshListUI()
    local len = self.registerMaxSeat
    local list = self.RegisterList
    if not list.IsListViewInit then
        list:InitGridView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(list, len)
    end
end

function CatHouseRegisterPanel:OnGetItemByIndex(listView, index)
    if index < 0 then
        return
    end
    local cell = listView:NewListViewItem(CellName)
    ---@type Engine.Modules.LuaBehaviour
    local node = GetLuaBehaviour(cell.gameObject, CatHouseRegisterCellEnvPath)
    local position  = index + 1
    ---@type CatHouseRegisterCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        --是否需要cell的init的逻辑
        node:Init()
        nodeEnv = node.Env
        -- nodeEnv:SetSelectCallback(function()
        --     -- self:FreshRallyNodeSelectState(self.index, false)
        --     self.index = position
        -- end)
    else
        nodeEnv = node.Env
    end
    if nodeEnv then
        nodeEnv:FreshUI(self.rallyId2Data[position], position, self.maxSignUpNum)
    end
    return cell

end

function CatHouseRegisterPanel:FreshRallyNode(rallyId, rallyData)
    local item = self.RegisterList:GetShownItemByItemIndex(rallyId - 1)
    if item == nil then return end
    ---@type CatHouseRegisterCell
    local nodeEnv = CfUtils.GetLuaScr(item.gameObject, CatHouseRegisterCellEnvPath)
    if nodeEnv then
        nodeEnv:FreshUI(rallyData, rallyId, self.maxSignUpNum)
    end
end


