function CatHouseRegisterPanel:OnEventCatHouseTimeChange()
    local cdCount = 0
    for rallyId, rallyData in pairs(self.rallyId2Data) do
        self:FreshRallyNode(rallyId, rallyData)
        if rallyData.remainTime > 0 then
            cdCount = cdCount + 1
        end
    end
    if cdCount == 0 then
        self:RemoveListener()
    end
end

