function CatHouseRegisterPanel:OnEventRequestCompleteAction(errCode, path)
    if checkNumber(errCode) ~= 0 then return end

    if path == Interfaces.CatHouseUnlockRallySignUpLimit then
        self:InitSignUpInfo()
        self:FreshListUI()
    end
end

function CatHouseRegisterPanel:OnEventRallyReplayHatchAction()
    self:InitSignUpInfo()
    self:FreshListUI()
end

